  "adventure.narrative.extra43": "Girá el celular",
  "adventure.narrative.extra44": "El final se ve mejor en horizontal. La historia te espera.",
  "adventure.narrative.extra45": "Ver en horizontal",
  "adventure.narrative.extra46": "Ver en vertical",
